import {inject, Injectable} from '@angular/core';
import * as pdfMake from 'pdfmake/build/pdfmake';
import * as pdfFonts from 'pdfmake/build/vfs_fonts';
import {Platform} from "@ionic/angular";
import {Directory, Filesystem} from "@capacitor/filesystem";
import {Share} from "@capacitor/share";
import {InternalControlsService} from "../internal-controls-service";
import {FormSegment, formSegmentDefaultSettings} from "../../interface/form-segment";

(<any>pdfMake).addVirtualFileSystem(pdfFonts);

@Injectable({
  providedIn: 'root',
})
export class PdfExport {


  private platform = inject(Platform);
  private internalControlsService = inject(InternalControlsService);

  private formSegment: FormSegment[] = formSegmentDefaultSettings();

  constructor() {
  }

  /**
   * Retourne une promesse contenant le Base64 du PDF
   */
  private getPdfBase64(pdfDocGenerator: any): Promise<string> {
    return new Promise((resolve, reject) => {
      pdfDocGenerator.getBase64((data: string) => {
        if (data) {
          resolve(data);
        } else {
          reject(new Error("Impossible de générer le Base64 du PDF"));
        }
      });
    });
  }

  /**
   * Génère et exporte le document PDF
   * @param docDefinition Configuration et contenu du document pdfMake
   * @param fileName Nom du fichier (ex: 'facture.pdf')
   */
  async generateAndExportPdf(docDefinition: any, fileName: string) {
    const pdfDocGenerator = pdfMake.createPdf(docDefinition);

// Mode Mobile Natif
    if (this.platform.is('hybrid')) {
      try {

        const base64 = await this.getPdfBase64(pdfDocGenerator);

        // 1. Enregistrement du fichier dans le stockage local de l'application
        const savedFile = await Filesystem.writeFile({
          path: fileName,
          data: base64,
          directory: Directory.Cache
        });

        // 2. Ouverture de la boîte de dialogue native pour ouvrir ou sauvegarder le PDF
        await Share.share({
          title: 'Ouvrir le document PDF',
          url: savedFile.uri,
          dialogTitle: 'Ouvrir ou partager le document PDF'
        });

      } catch (e) {
        console.error("Erreur lors de l'enregistrement ou du partage du PDF natif", e);
      }
      //Mode web
    } else {
      console.log("Mode web");
      await pdfDocGenerator.download(fileName);
    }
  }

  async exportDocument() {
    await this.generateAndExportPdf({
      pageOrientation: 'landscape',
      background: function(currentPage: number) {
        if(currentPage === 1) return null
        return {
          image: 'data:image/png;base64,',
          opacity: 0.15,
          alignment: 'center',
          absolutePosition: {x: 0, y: 50}
        };
        },
      footer: function(currentPage: number, pageCount: number){
        return [
          {text: `Page ${currentPage} sur ${pageCount}`, alignment: 'center'},
          {text: `${new Date().toLocaleDateString()}`, fontSize: 10, alignment: 'right', margin: [0, 0, 20, 20]}
        ]
      },
      content: [
        {
          table: {
            widths: ['*'],
            body: [
              [
                {
                  stack: [
                    {
                      text: 'Rapport des contrôles internes', style: 'header'
                    },
                    {
                      image: 'data:image/png;base64,',
                      style: 'subheader',
                      height: 280
                    },
                  ],
                  margin: [0, 100, 0, 0]
                }
              ]
            ]
          },
          layout: 'noBorders'
        },
        {text: '', pageBreak: 'after'},
        {
          style:'internalControlsTable',
          table: {
            widths: ['auto','auto','auto',...Array(this.formSegment.length).fill('auto'), 'auto'],
            body: [
              [
                {text: 'Date', style: 'internalControlsTableHeader'},
                {text: 'Agent', style: 'internalControlsTableHeader'},
                {text: 'Site', style: 'internalControlsTableHeader'},
                ...this.formSegment.map((segment) =>
                    ({text: segment.displayName, style: 'internalControlsTableHeader'})),
                {text: 'Observation', style: 'internalControlsTableHeader'},
              ],
              ...this.internalControlsService.internalControls.map((ic) => {
                return [
                  {text: ic.entryDateDisplay, style: 'internalControlsTableData', alignment: 'center'},
                  {text: ic.agentName, style: 'internalControlsTableData'},
                  {text: ic.domainName, style: 'internalControlsTableData'},
                  ...ic.booleans.map((segment) =>
                    ({text :segment.value ? 'Oui' : 'Non',style:'internalControlsTableData', alignment: 'center', color: segment.value ? 'green' : 'red'})),
                  {text: ic.comment, style: 'internalControlsTableData', lineHeight: 1.2}
                ]}),
            ],
          },
          layout: {
            vLineWidth: () => 0.25,
            hLineWidth: () => 0.25,
            hLineColor: () => '#bcc2cd',
            vLineColor: () => '#bcc2cd',
          }
        },
        {
          columns: [
            {text: 'AGP\n27 route du pont de la bique\n07100 Roiffieux', fontSize: 9, color: '#333333', lineHeight: 1.2},
            {text: 'Tél : 09 73 31 38 16\nEmail : contact@agencegayvalletprotection.com\nWeb : www.agencegayvalletprotection.com', fontSize: 9, color: '#333333', alignment: 'right', lineHeight: 1.2
            }
          ],
          marginBottom: 15
        },
        {
          text:'SASU au capital de 19 008€ - RCS d\'Aubenas 438 965 873 - SIRET 438 965 873 000 39 - TVA FR 23 438 965 873 - Code NAF 8010Z', fontSize: 8, color: '#666666', alignment: 'center', marginBottom: 8
        },
        {
          text:'Autorisation Administrative N° AUT-007-2112-07-15-20130338518 délivrée par le CNAPS Sud-Est.\nArticle L612-14 du CSI : « L’autorisation d’exercice ne confère aucune prérogative de puissance publique à l’entreprise ou aux personnes qui en bénéficient ».', fontSize: 8, alignment: 'center',lineHeight: 1.3, color: '#888888',
        }
      ],
      styles: {
        header: {fontSize: 22, bold: true, margin: [0, 0, 0, 10], alignment: 'center'},
        subheader: {alignment: 'center'},
        internalControlsTableData: {margin: [0, 3, 0, 3], fontSize: 9, color: '#2b3a4a', fillColor:'#eef3f8'},
        internalControlsTableHeader: {margin: [0, 4, 0, 4], fontSize: 10, bold: true, alignment: 'center', characterSpacing: 1, fillColor: '#0f2f60', color: '#ffffff'},
        internalControlsTable: {marginBottom: 15}
      }
    }, 'rapport-controles.pdf');
  }
}
